shell_commands:
python3 - <<'EOF'
p='src/orchestration/orchestratorHelpers.test.ts'
s=open(p).read()
old="""  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });
"""
new="""  it('returns the next usage when nothing has accumulated yet', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
  });

  it('keeps the accumulated usage when the next round reports none', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });
"""
assert old in s
open(p,'w').write(s.replace(old,new))
p='specs/hal-engine-architecture/spec.md'
s=open(p).read()
anchor="- Usage an earlier round reported is kept when a later round reports none, so a tool round does not erase the token count ([validated by: keeps the usage an earlier round reported when a later round reports none](../../src/orchestration/chatOrchestrator.test.ts#L527)).\n"
assert anchor in s
T='../../src/orchestration/orchestratorHelpers.test.ts'
add=f"""- Two rounds' usage combine by summing each token field ([validated by: sums token fields when both operands are defined]({T}#L29)).
- The first round to report usage starts the total from its own counts ([validated by: returns the next usage when nothing has accumulated yet]({T}#L35)).
- A round that reports no usage leaves the running total unchanged rather than making it `undefined` ([validated by: keeps the accumulated usage when the next round reports none]({T}#L40)).
- When neither the total nor the round has usage, the result stays `undefined` ([validated by: returns undefined when both operands are undefined]({T}#L45)).
"""
open(p,'w').write(s.replace(anchor,anchor+add))
EOF
grep -n "it(" src/orchestration/orchestratorHelpers.test.ts
